create or replace function public.can_upload_developer_guard_avatar_rc1(p_guard_id uuid,p_object_name text) returns boolean language plpgsql security definer set search_path=public set row_security=off stable as $$ declare v_user uuid; begin if auth.uid() is null or public.current_role()<>'platform_admin'::public.app_role then return false; end if; select user_id into v_user from public.guards where id=p_guard_id; if v_user is null then return false; end if; return split_part(p_object_name,'/',1)=v_user::text and split_part(p_object_name,'/',2)='developer-avatar'; end $$;
revoke all on function public.can_upload_developer_guard_avatar_rc1(uuid,text) from public,anon;
grant execute on function public.can_upload_developer_guard_avatar_rc1(uuid,text) to authenticated,service_role;
drop policy if exists guard_avatars_developer_insert on storage.objects;
create policy guard_avatars_developer_insert on storage.objects for insert to authenticated with check(bucket_id='guard-avatars' and split_part(name,'/',2)='developer-avatar' and exists(select 1 from public.guards g where g.user_id::text=split_part(name,'/',1) and public.can_upload_developer_guard_avatar_rc1(g.id,name)));
